export function RankTable(n,t){const a=n[t]||[];if(0===a.length)return'<div class="no-results">No ranks available for this service.</div>';let r="";return`\n        <div class="rank-table-wrapper">\n            <table class="rank-table">\n                <thead>\n                    <tr>\n                        <th>Rank</th>\n                        <th>Abbreviation</th>\n                        <th>NATO Eqvt.</th>\n                        <th>Pay Level</th>\n                        <th>Description</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    ${a.map(n=>{let t="";return n.grade!==r&&(r=n.grade,t=`<tr class="grade-header"><td colspan="5">${n.grade}</td></tr>`),`\n            ${t}\n            <tr>\n                <td class="rank-name">${n.rank}</td>\n                <td class="rank-abbr">${n.abbr}</td>\n                <td class="rank-nato">${n.natoEquivalent}</td>\n                <td class="rank-pay">${n.payLevel}</td>\n                <td class="rank-desc">${n.description}</td>\n            </tr>\n        `}).join("")}\n                </tbody>\n            </table>\n        </div>\n    `}